<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/app/bootstrap.php';
$admin=require_role(['owner','admin','operations','redeemer']);
$pdo=Database::connection();$notice=null;$error=null;$ticketCode=trim((string)($_GET['code']??$_POST['ticket_code']??''));$ticket=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf_or_fail();
 $ticketCode=trim((string)($_POST['ticket_code']??''));
 try{
  $pdo->beginTransaction();
  $q=$pdo->prepare('SELECT t.id ticket_id,t.ticket_code,t.quantity,t.status ticket_status,b.id booking_id,b.booking_code,b.participants,b.total_amount,b.currency,b.payment_status,b.ticket_status booking_ticket_status,b.activity_date,b.activity_time,c.full_name,p.name package_name FROM tickets t JOIN bookings b ON b.id=t.booking_id JOIN customers c ON c.id=b.customer_id JOIN packages p ON p.id=b.package_id WHERE t.ticket_code=:code FOR UPDATE');
  $q->execute(['code'=>$ticketCode]);$row=$q->fetch();
  if(!$row)throw new DomainException('Ticket code was not found.');
  if($row['payment_status']!=='paid')throw new DomainException('Payment is not verified. Do not redeem this ticket.');
  if($row['ticket_status']!=='valid')throw new DomainException('This ticket has already been redeemed or voided.');
  $pdo->prepare("INSERT INTO redemptions (ticket_id,booking_id,redeemed_quantity,redeemed_by,notes) VALUES (:ticket,:booking,:qty,:admin,'Redeemed by admin portal')")->execute(['ticket'=>(int)$row['ticket_id'],'booking'=>(int)$row['booking_id'],'qty'=>(int)$row['quantity'],'admin'=>(int)$admin['id']]);
  $pdo->prepare("UPDATE tickets SET status='redeemed' WHERE id=:id AND status='valid'")->execute(['id'=>(int)$row['ticket_id']]);
  $pdo->prepare("UPDATE bookings SET ticket_status='redeemed',booking_status='completed' WHERE id=:id")->execute(['id'=>(int)$row['booking_id']]);
  $pdo->commit();$notice='Ticket '.$ticketCode.' was successfully redeemed.';
 }catch(DomainException $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}
 catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Ticket redemption failed: '.$e->getMessage());$error='Could not redeem ticket. Check the application log.';}
}
if($ticketCode!==''){
 $q=$pdo->prepare('SELECT t.id ticket_id,t.ticket_code,t.quantity,t.status ticket_status,b.id booking_id,b.booking_code,b.participants,b.total_amount,b.currency,b.payment_status,b.ticket_status booking_ticket_status,b.activity_date,b.activity_time,c.full_name,c.email,c.phone,p.name package_name FROM tickets t JOIN bookings b ON b.id=t.booking_id JOIN customers c ON c.id=b.customer_id JOIN packages p ON p.id=b.package_id WHERE t.ticket_code=:code LIMIT 1');
 $q->execute(['code'=>$ticketCode]);$ticket=$q->fetch()?:null;
}
$redeemed=$pdo->query("SELECT r.redeemed_at,r.redeemed_quantity,t.ticket_code,b.booking_code,b.activity_date,c.full_name,p.name package_name FROM redemptions r JOIN tickets t ON t.id=r.ticket_id JOIN bookings b ON b.id=r.booking_id JOIN customers c ON c.id=b.customer_id JOIN packages p ON p.id=b.package_id WHERE DATE(r.redeemed_at)=CURDATE() ORDER BY r.redeemed_at DESC")->fetchAll();
$pending=$pdo->query("SELECT t.ticket_code,t.status ticket_status,b.booking_code,b.activity_date,b.activity_time,b.total_amount,b.currency,b.payment_status,c.full_name,p.name package_name FROM tickets t JOIN bookings b ON b.id=t.booking_id JOIN customers c ON c.id=b.customer_id JOIN packages p ON p.id=b.package_id WHERE b.activity_date=CURDATE() AND t.status='valid' ORDER BY b.activity_time")->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Redeem tickets | BTA Admin</title><style>:root{--orange:#ff5a1f}*{box-sizing:border-box}body{margin:0;background:#f4f2ed;color:#191919;font:14px/1.5 Arial,sans-serif}.top{background:#151515;color:#fff;padding:18px 24px;display:flex;justify-content:space-between}.top a{color:#fff}.wrap{max-width:1200px;margin:auto;padding:28px 18px}.panel{background:#fff;border:1px solid #e2ded6;border-top:3px solid var(--orange);padding:20px;margin:18px 0}.lookup{display:flex;gap:10px;flex-wrap:wrap}.lookup input{flex:1;min-width:180px;padding:13px;border:1px solid #d7d2c9;font:inherit}.btn{padding:12px 15px;background:var(--orange);border:0;font-weight:900;cursor:pointer}.notice{padding:12px;background:#e5f4e7;margin:14px 0}.error{background:#fde8e5}.summary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.summary div{background:#f4f2ed;padding:12px}.summary small{display:block;color:#777}.summary strong{display:block;margin-top:4px;overflow-wrap:anywhere}.tablewrap{overflow-x:auto}table{border-collapse:collapse;width:100%}th,td{text-align:left;padding:11px;border-bottom:1px solid #e6e2da;white-space:nowrap}th{font-size:10px}.muted{color:#777;font-size:11px}@media(max-width:650px){.panel{padding:13px}.summary{grid-template-columns:1fr 1fr}.wrap{padding:20px 10px}}</style></head><body><header class="top"><strong>BALI TARANTULA <span style="color:#ff5a1f">ADMIN</span></strong><a href="index.php">← Dashboard</a></header><main class="wrap"><h1>Redeem ticket</h1><p>Verify the booking code and payment status before redeeming. A ticket can only be redeemed once.</p><?php if($notice):?><div class="notice"><?=e($notice)?></div><?php endif;?><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?><section class="panel"><form class="lookup" method="get"><input name="code" value="<?=e($ticketCode)?>" placeholder="Enter ticket code, e.g. BTA-TK-..." required><button class="btn">CHECK TICKET</button></form></section>
<?php if($ticket):?><section class="panel"><h2>Ticket details</h2><div class="summary"><div><small>Ticket code</small><strong><?=e($ticket['ticket_code'])?></strong></div><div><small>Booking code</small><strong><?=e($ticket['booking_code'])?></strong></div><div><small>Guest</small><strong><?=e($ticket['full_name'])?></strong></div><div><small>Activity</small><strong><?=e($ticket['package_name'])?></strong></div><div><small>Activity date / time</small><strong><?=e($ticket['activity_date'])?> <?=e(substr((string)$ticket['activity_time'],0,5))?></strong></div><div><small>Guests / total price</small><strong><?=(int)$ticket['participants']?> guests · <?=e($ticket['currency'])?> <?=number_format((float)$ticket['total_amount'],2)?></strong></div><div><small>Payment</small><strong><?=e($ticket['payment_status'])?></strong></div><div><small>Ticket status</small><strong><?=e($ticket['ticket_status'])?></strong></div></div>
<?php if($ticket['payment_status']==='paid' && $ticket['ticket_status']==='valid'):?><form method="post" style="margin-top:18px" onsubmit="return confirm('Confirm that the activity has been provided and this ticket should be redeemed?');"><?=csrf_field()?><input type="hidden" name="ticket_code" value="<?=e($ticket['ticket_code'])?>"><button class="btn">CONFIRM REDEEM</button></form><?php elseif($ticket['payment_status']!=='paid'):?><p>Payment must be verified before redemption.</p><?php else:?><p>This ticket is already redeemed or void.</p><?php endif;?></section><?php elseif($ticketCode!==''):?><section class="panel"><p>No ticket was found for that code.</p></section><?php endif;?>
<section class="panel"><h2>Today's redemption log</h2><div class="tablewrap"><table><thead><tr><th>TIME</th><th>TICKET</th><th>BOOKING</th><th>GUEST</th><th>PACKAGE</th><th>QTY</th></tr></thead><tbody><?php foreach($redeemed as $r):?><tr><td><?=e($r['redeemed_at'])?></td><td><?=e($r['ticket_code'])?></td><td><?=e($r['booking_code'])?></td><td><?=e($r['full_name'])?></td><td><?=e($r['package_name'])?></td><td><?=(int)$r['redeemed_quantity']?></td></tr><?php endforeach;?><?php if(!$redeemed):?><tr><td colspan="6">No tickets redeemed today.</td></tr><?php endif;?></tbody></table></div></section>
<section class="panel"><h2>Today's tickets not yet redeemed</h2><div class="tablewrap"><table><thead><tr><th>TIME</th><th>TICKET</th><th>BOOKING</th><th>GUEST</th><th>PACKAGE</th><th>PAYMENT</th><th>TOTAL</th></tr></thead><tbody><?php foreach($pending as $r):?><tr><td><?=e(substr((string)$r['activity_time'],0,5))?></td><td><?=e($r['ticket_code'])?></td><td><?=e($r['booking_code'])?></td><td><?=e($r['full_name'])?></td><td><?=e($r['package_name'])?></td><td><?=e($r['payment_status'])?></td><td><?=e($r['currency'])?> <?=number_format((float)$r['total_amount'],2)?></td></tr><?php endforeach;?><?php if(!$pending):?><tr><td colspan="7">No valid tickets for today.</td></tr><?php endif;?></tbody></table></div></section></main></body></html>